 58	const SPACE_COLUMNS = "id, name, platform, url";
 59	
 60	const getValidSpaces = (spaces: SharedSpace[]): SharedNodeSpace[] =>
 61	  spaces.flatMap((space): SharedNodeSpace[] => {
 62	    if (
 63	      typeof space.id !== "number" ||
 64	      typeof space.name !== "string" ||
 65	      space.platform === null ||
 66	      typeof space.url !== "string"
 67	    )
 68	      return [];
 69	    return [
 70	      {
 71	        id: space.id,
 72	        name: space.name,
 73	        platform: space.platform,
 74	        url: space.url,
 75	      },
 76	    ];
 77	  });
 78	
 79	export const buildSharedNodes = ({
 80	  nodes,
 81	  directContents,
 82	  fullContentSummaries,
 83	  spaces,
 84	}: SharedNodeRows): SharedNode[] => {
 85	  const spacesById = new Map(
 86	    getValidSpaces(spaces).map((space) => [space.id, space]),
 87	  );
 88	  const spaceMap = Object.fromEntries(
 89	    [...spacesById].map(([id, space]) => [id, space.url]),
 90	  );
 91	
 92	  return groupDbNodeRows({ nodes, directContents, fullContentSummaries })
 93	    .flatMap((row): SharedNode[] => {
 94	      let resolved: ResolvedDbNode;
 95	      try {
 96	        resolved = resolveDbNode({ row, spaceMap });
 97	      } catch {
 98	        return [];
 99	      }
100	      const space = spacesById.get(resolved.spaceId)!;
101	
102	      return [
103	        {
104	          rid: resolved.rid,
105	          sourceLocalId: resolved.localId,
106	          schemaId: resolved.schemaId,
107	          spaceId: resolved.spaceId,
108	          spaceName: space.name,
109	          spaceUri: space.url,
110	          platform: space.platform,
111	          title: resolved.title,
112	          coreTitle: row.concept.core_title ?? undefined,
113	          created: resolved.created,
114	          lastModified: resolved.modifiedAt,
115	          authorId: resolved.direct.author_id ?? undefined,
116	          directMetadata: resolved.direct.metadata,
117	          slots: resolved.slots,
118	        },
119	      ];
120	    })
121	    .sort(
122	      (left, right) =>
123	        Date.parse(right.lastModified) - Date.parse(left.lastModified) ||
124	        left.title.localeCompare(right.title),
125	    );
126	};
127	
128	const getAssociatedSpaces = async ({
129	  client,
130	  concepts,
131	  currentSpace,
132	  currentSpaceId,
133	}: {
134	  client: DGSupabaseClient;
135	  concepts: DbNodeConcept[];
136	  currentSpace?: SharedSpace;
137	  currentSpaceId?: number;
138	}): Promise<SharedSpace[]> => {
139	  const associatedSpaceIds = new Set(
140	    [
141	      ...concepts.map((cpt) => cpt.space_id),
142	      ...concepts.flatMap((cpt) =>
143	        cpt.concepts_of_relation.map((cr) => cr.space_id),
144	      ),
145	    ].filter((id) => id !== null),
146	  );
147	  if (currentSpace !== undefined) {
148	    currentSpaceId = currentSpace.id ?? currentSpaceId;
149	  } else if (currentSpaceId !== undefined)
150	    associatedSpaceIds.add(currentSpaceId);
151	  const spaces: SharedSpace[] = [];
152	  if (currentSpace !== undefined && currentSpaceId !== undefined) {
153	    spaces.push(currentSpace);
154	    associatedSpaceIds.delete(currentSpaceId);
155	  }
156	  if (associatedSpaceIds.size > 0) {
157	    const { data, error } = await client
158	      .from("my_spaces")
159	      .select(SPACE_COLUMNS)
160	      .in("id", [...associatedSpaceIds]);
161	    if (error) throw error;
162	    spaces.push(...data);
163	  }
164	  return spaces;
165	};
166	
167	const getSharedNodeRows = async ({
168	  client,
169	  currentSpaceId,
170	}: {
171	  client: DGSupabaseClient;
172	  currentSpaceId: number;
173	}): Promise<SharedNodeRows> => {
174	  const [conceptsResponse, directResponse, fullResponse] = await Promise.all([
175	    client
176	      .from("my_concepts")
177	      .select(CONCEPT_COLUMNS_WITH_SLOTS)
178	      .neq("space_id", currentSpaceId)
179	      .eq("is_schema", false)
180	      .eq("is_relation", false),
181	    client
182	      .from("my_contents")
183	      .select(DIRECT_CONTENT_COLUMNS)
184	      .neq("space_id", currentSpaceId)
185	      .eq("variant", "direct"),
186	    client
187	      .from("my_contents")
188	      .select(FULL_CONTENT_SUMMARY_COLUMNS)
189	      .neq("space_id", currentSpaceId)
190	      .eq("variant", "full"),
191	  ]);
192	  if (conceptsResponse.error) throw conceptsResponse.error;
193	  if (directResponse.error) throw directResponse.error;
194	  if (fullResponse.error) throw fullResponse.error;
195	  const spaces = await getAssociatedSpaces({
196	    client,
197	    concepts: conceptsResponse.data,
198	    currentSpaceId,
199	  });
200	
201	  return {
202	    nodes: conceptsResponse.data,
203	    directContents: directResponse.data,
204	    fullContentSummaries: fullResponse.data,
205	    spaces,
206	  };
207	};
208	
209	export const listGroupSharedNodes = async ({
210	  client,
211	  currentSpaceId,
212	}: {
213	  client: DGSupabaseClient;
214	  currentSpaceId: number;
215	}): Promise<SharedNode[]> => {
216	  const rows = await getSharedNodeRows({ client, currentSpaceId });
217	  return buildSharedNodes(rows);
218	};
219	
220	const toSharedNodeListing = async ({
221	  client,
222	  spaces,
223	  ...rows
224	}: SharedNodeRows & {
225	  client: DGSupabaseClient;
226	}): Promise<SharedNodeListing> => {
227	  const validSpaces = getValidSpaces(spaces);
228	  const nodes = await dbNodesToCrossApp({
229	    client,
230	    ...rows,
231	    spaceMap: Object.fromEntries(validSpaces.map(({ id, url }) => [id, url])),
232	  });
233	  return {
234	    nodes: nodes.sort(
235	      (left, right) =>
236	        right.modifiedAt.getTime() - left.modifiedAt.getTime() ||
237	        left.content.direct.value.localeCompare(right.content.direct.value),
238	    ),
239	    spaces: Object.fromEntries(validSpaces.map((space) => [space.url, space])),
240	  };
241	};
242	
243	export const listGroupSharedCrossAppNodes = async ({
244	  client,
245	  currentSpaceId,
246	}: {
247	  client: DGSupabaseClient;
248	  currentSpaceId: number;
249	}): Promise<SharedNodeListing> => {
250	  const rows = await getSharedNodeRows({ client, currentSpaceId });
251	  return toSharedNodeListing({ client, ...rows });
252	};
253	
254	export const getSharedNodeSpace = ({
255	  node,
256	  spaces,
257	}: {
258	  node: DbCrossAppNode;
259	  spaces: SharedNodeListing["spaces"];
260	}): SharedNodeSpace => {
261	  const space = spaces[ridToSpaceUriAndLocalId(node.rid).spaceUri];
262	  if (space === undefined) throw new Error(`Missing the space of ${node.rid}`);
263	  return space;
264	};
265	
266	export const getNodeTypeRid = (node: DbCrossAppNode): string =>
267	  spaceUriAndLocalIdToRid(
268	    ridToSpaceUriAndLocalId(node.rid).spaceUri,
269	    node.nodeType,
270	    "schema",
271	  );
272	
273	export const getSharedNodeByRid = async ({
274	  client,
275	  rid,
276	}: {
277	  client: DGSupabaseClient;
278	  rid: string;
279	}): Promise<{ node: DbCrossAppNode; space: SharedNodeSpace } | null> => {
280	  const { spaceUri, sourceLocalId } = ridToSpaceUriAndLocalId(rid);
281	  const spaceResponse = await client
282	    .from("my_spaces")
283	    .select(SPACE_COLUMNS)
284	    .eq("url", spaceUri)
285	    .maybeSingle();
286	  if (spaceResponse.error) throw spaceResponse.error;
287	  const space = spaceResponse.data;
288	  if (!space || typeof space.id !== "number") return null;
289	
290	  const [conceptsResponse, directResponse, fullResponse] = await Promise.all([
291	    client
292	      .from("my_concepts")
293	      .select(CONCEPT_COLUMNS_WITH_SLOTS)
294	      .eq("space_id", space.id)
295	      .eq("source_local_id", sourceLocalId)
296	      .eq("is_schema", false)
297	      .eq("is_relation", false),
298	    client
299	      .from("my_contents")
300	      .select(DIRECT_CONTENT_COLUMNS)
301	      .eq("space_id", space.id)
302	      .eq("source_local_id", sourceLocalId)
303	      .eq("variant", "direct"),
304	    client
305	      .from("my_contents")
306	      .select(FULL_CONTENT_SUMMARY_COLUMNS)
307	      .eq("space_id", space.id)
308	      .eq("source_local_id", sourceLocalId)
309	      .eq("variant", "full"),
310	  ]);
311	  if (conceptsResponse.error) throw conceptsResponse.error;
312	  if (directResponse.error) throw directResponse.error;
313	  if (fullResponse.error) throw fullResponse.error;
314	  const spaces = await getAssociatedSpaces({
315	    client,
316	    concepts: conceptsResponse.data,
317	    currentSpace: space,
318	  });
319	
320	  const listing = await toSharedNodeListing({
321	    client,
322	    nodes: conceptsResponse.data,
323	    directContents: directResponse.data,
324	    fullContentSummaries: fullResponse.data,
325	    spaces,
326	  });
327	  const [node] = listing.nodes;
328	  if (!node) {
329	    if (conceptsResponse.data.length === 0) return null;
330	    throw new Error("its source is shared but could not be read");
331	  }
332	  return { node, space: getSharedNodeSpace({ node, spaces: listing.spaces }) };
333	};

