 15	export const REFRESH_ERROR_TYPE = "Imported node refresh failed";
 16	const REFRESH_ERROR_OPERATION = "refresh-imported-node";
 17	
 18	type RefreshImportedNodeResult = {
 19	  status: "refreshed" | "skipped" | "failed";
 20	  message: string;
 21	  warning?: string;
 22	};
 23	
 24	// A relation published after both of its ends were imported arrives only with a later
 25	// import or refresh. Returns a warning when some relations could not be imported.
 26	export const importRelationsAfterRefresh = async (
 27	  client: DGSupabaseClient,
 28	): Promise<string | undefined> => {
 29	  try {
 30	    const context = await getSupabaseContext();
 31	    if (!context)
 32	      return "Could not import relations: could not connect to shared persistence.";
 33	    // Skipped relations are not reported: they need not involve the refreshed node.
 34	    const { failures } = await importSharedRelations(client, context.spaceId);
 35	    if (failures.length === 0) return undefined;
 36	    return failures.length === 1
 37	      ? "1 relation could not be imported."
 38	      : `${failures.length} relations could not be imported.`;
 39	  } catch (error) {
 40	    internalError({
 41	      error,
 42	      type: REFRESH_ERROR_TYPE,
 43	      context: { operation: "import-relations-after-refresh" },
 44	      sendEmail: false,
 45	    });
 46	    return `Could not import relations: ${getErrorMessage(error)}`;
 47	  }
 48	};
 49	
 50	const joinWarnings = (...warnings: (string | undefined)[]) => {
 51	  const present = warnings.filter((w) => w !== undefined);
 52	  return present.length > 0 ? { warning: present.join(" ") } : {};
 53	};
 54	
 55	// Refresh-all passes `importRelations: false` and imports relations once at the end.
 56	export const refreshImportedNode = async ({
 57	  pageUid,
 58	  force,
 59	  importRelations = true,
 60	}: {
 61	  pageUid: string;
 62	  force: boolean;
 63	  importRelations?: boolean;
 64	}): Promise<RefreshImportedNodeResult> => {
 65	  try {
 66	    const title = getPageTitleByPageUid(pageUid);
 67	    const identity = readImportedSourceIdentity(pageUid);
 68	    if (!identity)
 69	      return {
 70	        status: "failed",
 71	        message: `"${title}" has no stored source identity, so it cannot be refreshed.`,
 72	      };
 73	
 74	    const client = await getLoggedInClient();
 75	    if (!client)
 76	      return {
 77	        status: "failed",
 78	        message: "Could not connect to shared persistence.",
 79	      };
 80	
 81	    const sharedNodeWithSpace = await getSharedNodeByRid({
 82	      client,
 83	      rid: identity.sourceNodeRid,
 84	    });
 85	    if (!sharedNodeWithSpace)
 86	      return {
 87	        status: "failed",
 88	        message: `The source of "${title}" is no longer shared with your groups, so it cannot be refreshed.`,
 89	      };
 90	    const { node: sharedNode, space } = sharedNodeWithSpace;
 91	
 92	    const nodeTypesBySchemaRid = await resolveSharedNodeTypes({
 93	      client,
 94	      sharedNodes: [sharedNode],
 95	      spaces: { [space.url]: space },
 96	    });
 97	    const result = await materializeSharedNode({
 98	      client,
 99	      sharedNode,
100	      space,
101	      nodeType: nodeTypesBySchemaRid.get(getNodeTypeRid(sharedNode)),
102	      force,
103	    });
104	    if (!result.success) {
105	      internalError({
106	        error: new Error(result.error.message),
107	        type: REFRESH_ERROR_TYPE,
108	        context: {
109	          operation: REFRESH_ERROR_OPERATION,
110	          pageUid,
111	          stage: result.error.stage,
112	        },
113	        sendEmail: false,
114	      });
115	      return { status: "failed", message: result.error.message };
116	    }
117	    if (result.pageUid !== pageUid)
118	      return {
119	        status: "failed",
120	        message: `A different page ("${getPageTitleByPageUid(result.pageUid)}") is linked to the same source and was refreshed instead.`,
121	      };
122	    const relationWarning = importRelations
123	      ? await importRelationsAfterRefresh(client)
124	      : undefined;
125	    if (result.action === "skipped")
126	      return {
127	        status: "skipped",
128	        message: `"${sharedNode.content.direct.value}" is already up to date.`,
129	        ...joinWarnings(relationWarning),
130	      };
131	    return {
132	      status: "refreshed",
133	      message: `Refreshed "${sharedNode.content.direct.value}" from ${space.name}.`,
134	      ...joinWarnings(result.warning, relationWarning),
135	    };
136	  } catch (error) {
137	    internalError({
138	      error,
139	      type: REFRESH_ERROR_TYPE,
140	      context: { operation: REFRESH_ERROR_OPERATION, pageUid },
141	      sendEmail: false,
142	    });
143	    return {
144	      status: "failed",
145	      message: `Could not refresh this page: ${getErrorMessage(error)}`,
146	    };
147	  }
148	};

