371	        error: relationsError,
372	        type: IMPORT_ERROR_TYPE,
373	        context: { operation: RELATIONS_IMPORT_ERROR_OPERATION },
374	        sendEmail: false,
375	        userMessage: `The relations were not imported: ${getErrorMessage(relationsError)}`,
376	      });
377	    }
378	  };
379	
380	  const retryRelations = async (): Promise<void> => {
381	    setRetryingRelations(true);
382	    try {
383	      const client = await getLoggedInClient();
384	      if (!client) throw new Error(CONNECTION_ERROR_MESSAGE);
385	      await importRelations(client);
386	    } catch (retryError) {
387	      internalError({
388	        error: retryError,
389	        type: IMPORT_ERROR_TYPE,
390	        context: { operation: RELATIONS_IMPORT_ERROR_OPERATION },
391	        sendEmail: false,
392	        userMessage: getErrorMessage(retryError),
393	      });
394	    } finally {
395	      setRetryingRelations(false);
396	    }
