// Reproduces the DiscoverSharedNodesDialog H1 render path under React 18.2's legacy
// ReactDOM.render (what roamjs-components' renderOverlay uses): a reload that brings a node
// from a new space, while the list is sorted by space name.
const W = "/mnt/data/projects/discourse-graph/.claude/worktrees/eng-2091";
const { JSDOM } = require(`${W}/node_modules/.pnpm/jsdom@20.0.3/node_modules/jsdom`);
const dom = new JSDOM("<!doctype html><div id=root></div>");
global.window = dom.window;
global.document = dom.window.document;
global.navigator = dom.window.navigator;
const React = require(`${W}/node_modules/.pnpm/react@18.2.0/node_modules/react`);
const ReactDOM = require(
  `${W}/node_modules/.pnpm/react-dom@18.2.0_react@18.2.0/node_modules/react-dom`,
);
const { useState, useMemo, useEffect } = React;
const h = React.createElement;

const spaceA = { name: "A", url: "space-a" };
const spaceB = { name: "B", url: "space-b" };
const listings = [
  { nodes: [{ rid: "a1", spaceUri: "space-a" }], spaces: { "space-a": spaceA } },
  {
    nodes: [
      { rid: "a1", spaceUri: "space-a" },
      { rid: "b1", spaceUri: "space-b" },
    ],
    spaces: { "space-a": spaceA, "space-b": spaceB },
  },
];
let call = 0;
const discover = async () => listings[call++];

const getSharedNodeSpace = ({ node, spaces }) => {
  const space = spaces[node.spaceUri];
  if (space === undefined) throw new Error(`Missing the space of ${node.rid}`);
  return space;
};
const sortBySpaceName = (nodes, spaces) =>
  [...nodes].sort((l, r) =>
    getSharedNodeSpace({ node: l, spaces }).name.localeCompare(
      getSharedNodeSpace({ node: r, spaces }).name,
    ),
  );

const renders = [];
let reload;

const OldDialog = () => {
  const [nodes, setNodes] = useState([]);
  const [spaces, setSpaces] = useState({});
