  renders.push({ nodes: nodes.length, spaces: Object.keys(spaces).length, loading });
  return h("div", null, available.map((n) => h("span", { key: n.rid }, n.rid)));
};

const tick = () => new Promise((r) => setTimeout(r, 20));
const run = async (name, Component) => {
